import type {
  TransitManifest,
  TransitRoute,
  TransitStop,
} from '../types/transit-data';

/**
 * Transit snapshot access.
 *
 * Static committed JSON under `public/data/transit/<city>/`, generated by
 * `scripts/fetch-transit-data.ts`. No API route is involved: the operator's
 * feed is fetched once at build time, so the deployed app never depends on
 * their server being reachable.
 */

const TRANSIT_BASE = '/data/transit';

export class TransitFetchError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'TransitFetchError';
    this.status = status;
  }
}

async function fetchJson<T>(url: string): Promise<T> {
  let response: Response;

  try {
    response = await fetch(url);
  } catch (cause) {
    throw new TransitFetchError(
      `Could not reach ${url}: ${cause instanceof Error ? cause.message : 'network error'}`,
      0,
    );
  }

  if (!response.ok) {
    throw new TransitFetchError(
      `Request for ${url} failed with ${response.status}`,
      response.status,
    );
  }

  return (await response.json()) as T;
}

export async function fetchTransitSnapshot(cityId: string): Promise<{
  manifest: TransitManifest;
  routes: TransitRoute[];
  stops: TransitStop[];
}> {
  // Three small files, fetched together: the whole snapshot is about 28 KB.
  const [manifest, routes, stops] = await Promise.all([
    fetchJson<TransitManifest>(`${TRANSIT_BASE}/${cityId}/manifest.json`),
    fetchJson<TransitRoute[]>(`${TRANSIT_BASE}/${cityId}/routes.json`),
    fetchJson<TransitStop[]>(`${TRANSIT_BASE}/${cityId}/stops.json`),
  ]);

  return { manifest, routes, stops };
}
